using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;

namespace NumeralPreview
{
    /// <summary>
    /// Renders the ten numeral sample graphs headlessly (see Numerals.g.cs, generated by
    /// tools/make_numeral_graphs.py). Usage: NumeralPreview [outDir] [digits, e.g. 038]
    /// </summary>
    internal static partial class Program
    {
        private static readonly Action<string>[] Numerals =
        {
            Numeral0, Numeral1, Numeral2, Numeral3, Numeral4, Numeral5, Numeral6, Numeral7, Numeral8, Numeral9,
        };

        private static int Main(string[] args)
        {
            var outDir = args.Length > 0 ? args[0] : "numeral-output";
            var only = args.Length > 1 ? args[1] : "0123456789";
            Directory.CreateDirectory(outDir);
            var failures = 0;
            foreach (var c in only)
            {
                var digit = c - '0';
                if (digit < 0 || digit > 9) continue;
                var sw = Stopwatch.StartNew();
                try
                {
                    Numerals[digit](outDir);
                    Console.WriteLine($"  ({sw.Elapsed.TotalSeconds:0.0}s)");
                }
                catch (Exception ex)
                {
                    failures++;
                    Console.WriteLine($"numeral {digit}: FAILED {ex.GetType().Name}: {ex.Message}");
                    Console.WriteLine(ex.StackTrace);
                }
            }
            return failures == 0 ? 0 : 1;
        }

        private static void Report(string digit, Dictionary<string, object> stats)
        {
            Console.Write($"numeral {digit}: {stats["layerCount"]} layers, {stats["pathCount"]} paths, " +
                          $"draw {Convert.ToDouble(stats["drawLength"]) / 1000:0.00} m, travel {Convert.ToDouble(stats["travelLength"]) / 1000:0.00} m, " +
                          $"outside page {stats["outsidePage"]}");
            if (Convert.ToInt32(stats["outsidePage"]) != 0) throw new InvalidOperationException("geometry outside the page");
            if (Convert.ToInt32(stats["pathCount"]) == 0) throw new InvalidOperationException("empty drawing");
        }
    }
}
